var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Free generation outside any constrained span.
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    // Use RenderedEndsWith to correctly detect "<<" even when space-prefixed by the tokenizer.
    if RenderedEndsWith(generated, "<<") {
      generated, insideConstrainedOut, currentConstrainedOut :=
        helpers.EnterObservedConstrainedSpan(lm, generated);
    }
  } else {
    // Inside a constrained span: hard-mask prevents {/} template variables.
    // Budget pressure: use CloseSpanWithinBudget with limited budget to avoid runaway loops.
    if maxSteps - steps <= 3 {
      var closeB: nat;
      if maxSteps - steps <= 3 {
        closeB := maxSteps - steps;
      } else {
        closeB := 3;
      }
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + closeB;
      break;
    }
    // Try closing if the expression is already complete.
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(
      lm, parser, generated, currentConstrainedOut
    );
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else if steps < maxSteps {
      // Advance one parser-valid token inside the span.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // Model signals done: close span with a small budget to find nearest complete prefix.
        if maxSteps > steps {
          var closeB: nat;
          if maxSteps - steps <= 20 {
            closeB := maxSteps - steps;
          } else {
            closeB := 20;
          }
          var cg2, ci2, cc2 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB
          );
          generated := cg2;
          insideConstrainedOut := ci2;
          currentConstrainedOut := cc2;
          steps := steps + closeB;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

